import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { MemoryCache } from "../src/menu/cache.ts";
import { MENU_TTL_MS, MenuService, type Menu, type MenuStore } from "../src/menu/menus.ts";
import { ItemUnavailableError, quoteOrder } from "../src/menu/checkout.ts";

// Reads take one round trip; writes take a few (they go to the primary and wait for the commit).
function memoryStore(menus: Menu[]): MenuStore & { loads: number } {
    const rows = new Map(menus.map((m) => [m.restaurantId, structuredClone(m)]));
    return {
        loads: 0,
        async loadMenu(id) {
            this.loads++;
            await tick();
            const menu = rows.get(id);
            return menu ? structuredClone(menu) : null;
        },
        async updateItem(id, itemId, changes) {
            await tick();
            await tick();
            await tick();
            const item = rows.get(id)?.items.find((i) => i.id === itemId);
            if (!item) return false;
            Object.assign(item, changes);
            return true;
        },
    };
}

function setup() {
    let now = Date.parse("2026-11-19T18:00:00Z");
    const store = memoryStore([{
        restaurantId: "taco-loco",
        items: [
            { id: "al-pastor", name: "Al pastor taco", priceCents: 450, available: true },
            { id: "horchata", name: "Horchata", priceCents: 300, available: true },
        ],
    }]);
    const menus = new MenuService(store, new MemoryCache<Menu>(() => now));
    return { store, menus, advance: (ms: number) => (now += ms) };
}

const price = (menu: Menu, id: string) => menu.items.find((i) => i.id === id)?.priceCents;

test("menus are served from the cache after the first read", async () => {
    const { store, menus } = setup();
    await menus.getMenu("taco-loco");
    await menus.getMenu("taco-loco");
    await quoteOrder(menus, "taco-loco", [{ itemId: "horchata", qty: 1 }]);
    assert.equal(store.loads, 1);
});

test("a price change shows up on the next read", async () => {
    const { menus } = setup();
    await menus.getMenu("taco-loco");
    await menus.updatePrice("taco-loco", "al-pastor", 500);
    assert.equal(price(await menus.getMenu("taco-loco"), "al-pastor"), 500);
});

test("a menu read while a price change is being saved doesn't keep the old price", async () => {
    const { menus } = setup();
    await menus.getMenu("taco-loco");
    const browsing = menus.getMenu("taco-loco");
    await Promise.all([menus.updatePrice("taco-loco", "al-pastor", 500), browsing, menus.getMenu("taco-loco")]);
    const after = await menus.getMenu("taco-loco");
    console.log("al-pastor price after the update finished:", price(after, "al-pastor"));
    assert.equal(price(after, "al-pastor"), 500);
});

test("an item marked sold out can't be ordered, even if customers were browsing during the change", async () => {
    const { menus } = setup();
    await menus.getMenu("taco-loco");
    await Promise.all([menus.setAvailable("taco-loco", "horchata", false), menus.getMenu("taco-loco")]);
    await assert.rejects(quoteOrder(menus, "taco-loco", [{ itemId: "horchata", qty: 2 }]), ItemUnavailableError);
});

test("checkout charges the new price once the change is saved", async () => {
    const { menus } = setup();
    const lines = [{ itemId: "al-pastor", qty: 3 }, { itemId: "horchata", qty: 1 }];
    assert.equal((await quoteOrder(menus, "taco-loco", lines)).subtotalCents, 1650);
    await Promise.all([menus.updatePrice("taco-loco", "al-pastor", 400), quoteOrder(menus, "taco-loco", lines)]);
    assert.equal((await quoteOrder(menus, "taco-loco", lines)).subtotalCents, 1500);
});

test("cached menus expire after the TTL", async () => {
    const { store, menus, advance } = setup();
    await menus.getMenu("taco-loco");
    advance(MENU_TTL_MS - 1);
    await menus.getMenu("taco-loco");
    assert.equal(store.loads, 1);
    advance(1);
    await menus.getMenu("taco-loco");
    assert.equal(store.loads, 2);
});

test("bad updates are rejected", async () => {
    const { menus } = setup();
    await assert.rejects(menus.updatePrice("taco-loco", "al-pastor", -5), /positive/);
    await assert.rejects(menus.updatePrice("taco-loco", "burrito", 900), /Unknown item/);
    assert.equal(price(await menus.getMenu("taco-loco"), "al-pastor"), 450);
});
